    s.textContent = "/* apiref_sidebar.css -- professional left-rail navigation for the API reference.\n *\n * Rendered by apiref_sidebar.js from window.APIREF_NAV (generated by\n * `apiref.py wire`). Scoped entirely under .apiref-nav so it cannot disturb\n * the rest of the alabaster theme. Indentation is capped at three visual\n * tiers no matter how deep the tree is, and labels wrap instead of being\n * clipped -- the two problems with the old globaltoc rail.\n */\n\n.apiref-nav {\n  --ap-pad: 0.2rem;           /* base inset for every row            */\n  --ap-step: 0.34rem;         /* extra inset per visual tier (max 2) */\n  --ap-rail: #d7deea;\n  --ap-line: #e6ebf3;\n  --ap-text: #26364a;\n  --ap-muted: #6d7d90;\n  --ap-accent: var(--pluss-accent, #0a7ca7);\n  --ap-accent-weak: #e9f4fa;\n  --ap-hover: #eef3f9;\n\n  box-sizing: border-box;\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  min-height: 0;\n  font-size: 0.875rem;\n  color: var(--ap-text);\n}\n\n.apiref-nav *,\n.apiref-nav *::before,\n.apiref-nav *::after {\n  box-sizing: border-box;\n}\n\n/* ---- header : title + filter (sticky) ---------------------------------- */\n.apiref-nav__head {\n  flex: 0 0 auto;\n  padding: 0.7rem 0.6rem 0.55rem;\n  border-bottom: 1px solid var(--ap-line);\n  background: var(--pluss-panel, #fff);\n}\n\n.apiref-nav__title {\n  display: block;\n  font-size: 0.95rem;\n  font-weight: 700;\n  letter-spacing: 0.01em;\n  color: #123047;\n  text-decoration: none;\n  margin-bottom: 0.5rem;\n}\n\n.apiref-nav__title:hover {\n  color: var(--ap-accent);\n}\n\n.apiref-nav__filter {\n  width: 100%;\n  padding: 0.4rem 0.55rem;\n  border: 1px solid var(--pluss-border, #d2dbe6);\n  border-radius: 7px;\n  font: inherit;\n  font-size: 0.83rem;\n  background: #fbfcfe;\n  color: var(--ap-text);\n}\n\n.apiref-nav__filter:focus {\n  outline: 2px solid var(--ap-accent-weak);\n  border-color: var(--ap-accent);\n}\n\n.apiref-nav__filter::placeholder {\n  color: var(--ap-muted);\n}\n\n/* ---- scroll region --------------------------------------------------- */\n.apiref-nav__scroll {\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  padding: 0.45rem 0.2rem 2rem;\n}\n\n.apiref-nav__scroll::-webkit-scrollbar {\n  width: 9px;\n}\n\n.apiref-nav__scroll::-webkit-scrollbar-thumb {\n  background: #cdd6e2;\n  border-radius: 6px;\n}\n\n/* ---- tree ---------------------------------------------------------------- */\n.apiref-nav__tree,\n.apiref-nav__children {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* One thin guide line per nested level. The per-level offset is deliberately\n * tiny (0.36rem) and stops compounding after three levels, so deep method\n * names keep almost the full rail width instead of being pushed off it. */\n.apiref-nav__children {\n  margin-inline-start: 0.42rem;\n  border-inline-start: 1px solid var(--ap-rail);\n}\n\n/* level 2 (members under an object) barely steps in; level 3+ not at all */\n.apiref-nav__children .apiref-nav__children {\n  margin-inline-start: 0.24rem;\n}\n\n.apiref-nav__children .apiref-nav__children .apiref-nav__children {\n  margin-inline-start: 0;\n  border-inline-start: 0;\n}\n\n/* collapsed by default; JS adds .is-open to the ancestors of the current page\n * and to whatever the reader expands (remembered in localStorage). */\n.apiref-nav__item > .apiref-nav__children {\n  display: none;\n}\n\n.apiref-nav__item.is-open > .apiref-nav__children {\n  display: block;\n}\n\n.apiref-nav__item[hidden] {\n  display: none;\n}\n\n.apiref-nav__row {\n  display: flex;\n  align-items: flex-start;\n  gap: 0.15rem;\n  border-radius: 6px;\n}\n\n.apiref-nav__row:hover {\n  background: var(--ap-hover);\n}\n\n/* chevron toggle */\n.apiref-nav__toggle {\n  flex: 0 0 0.7rem;\n  align-self: stretch;\n  min-height: 1.8rem;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--ap-muted);\n  cursor: pointer;\n  font: inherit;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.apiref-nav__toggle::before {\n  content: \"\";\n  width: 0;\n  height: 0;\n  border-top: 4px solid transparent;\n  border-bottom: 4px solid transparent;\n  border-left: 5px solid currentColor;\n  transition: transform 0.12s ease;\n}\n\n.apiref-nav__item.is-open > .apiref-nav__row > .apiref-nav__toggle::before {\n  transform: rotate(90deg);\n}\n\n/* leaf rows still align with rows that have a chevron */\n.apiref-nav__row.is-leaf {\n  padding-inline-start: 0.7rem;\n}\n\n.apiref-nav__link {\n  flex: 1 1 auto;\n  min-width: 0;\n  display: block;\n  padding: 0.32rem 0.4rem 0.32rem var(--ap-pad);\n  border-inline-start: 2px solid transparent;\n  color: inherit;\n  text-decoration: none;\n  line-height: 1.3;\n  white-space: normal;\n  overflow-wrap: break-word;   /* wrap long symbol names, never clip them */\n  word-break: break-word;\n  hyphens: none;\n}\n\n.apiref-nav__link:hover {\n  color: #0c5f83;\n}\n\n.apiref-nav__link.is-active {\n  background: var(--ap-accent-weak);\n  border-inline-start-color: var(--ap-accent);\n  color: #06557a;\n  font-weight: 700;\n}\n\n.apiref-nav__item.has-active > .apiref-nav__row > .apiref-nav__link {\n  color: #123047;\n}\n\n/* ---- per-type styling ------------------------------------------------- */\n.apiref-nav__item[data-type=\"family\"] > .apiref-nav__row > .apiref-nav__link {\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  color: #2a3a4d;\n}\n\n.apiref-nav__item[data-type=\"class\"] > .apiref-nav__row > .apiref-nav__link,\n.apiref-nav__item[data-type=\"options\"] > .apiref-nav__row > .apiref-nav__link,\n.apiref-nav__item[data-type=\"function\"] > .apiref-nav__row > .apiref-nav__link,\n.apiref-nav__item[data-type=\"page\"] > .apiref-nav__row > .apiref-nav__link {\n  font-family: SFMono-Regular, Consolas, \"Liberation Mono\", Menlo, monospace;\n  font-size: 0.83rem;\n}\n\n.apiref-nav__item[data-type=\"class\"] > .apiref-nav__row > .apiref-nav__link {\n  font-weight: 700;\n}\n\n.apiref-nav__item[data-type=\"options\"] > .apiref-nav__row > .apiref-nav__link::after {\n  content: \" \u00b7opts\";\n  color: var(--ap-muted);\n  font-size: 0.72rem;\n}\n\n.apiref-nav__item[data-type=\"method\"] > .apiref-nav__row > .apiref-nav__link {\n  font-family: SFMono-Regular, Consolas, \"Liberation Mono\", Menlo, monospace;\n  font-size: 0.8rem;\n  color: #45586c;\n}\n\n.apiref-nav__empty {\n  padding: 0.8rem 0.7rem;\n  color: var(--ap-muted);\n  font-size: 0.82rem;\n}\n\n/* The left rail is the one place children are enumerated. Sphinx still needs\n * the in-page {toctree} directives for prev/next wiring, but rendering them\n * as bullet lists in the body just duplicates the rail -- hide them. */\nbody.apiref-page div.body .toctree-wrapper {\n  display: none;\n}\n\n/* ---- host panel : take over alabaster's sidebar box ------------------- */\ndiv.sphinxsidebar:has(.apiref-nav) {\n  padding: 0;\n}\n\ndiv.sphinxsidebar:has(.apiref-nav) .sphinxsidebarwrapper {\n  padding: 0;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n}\n\n/* ---- narrow screens : collapsible panel above the content ------------ */\n@media (max-width: 1024px) {\n  /* stack the rail above the content instead of hiding it */\n  div.document:has(.apiref-nav) {\n    display: flex;\n    flex-direction: column;\n  }\n\n  div.sphinxsidebar:has(.apiref-nav) {\n    display: block;\n    position: static;\n    order: -1;\n    width: 100%;\n    max-height: none;\n    border-right: 0;\n    border-bottom: 1px solid var(--pluss-border, #d2dbe6);\n  }\n\n  div.documentwrapper:has(~ div.sphinxsidebar .apiref-nav),\n  div.document:has(.apiref-nav) div.documentwrapper {\n    margin-left: 0;\n    width: 100%;\n  }\n\n  .apiref-nav {\n    height: auto;\n  }\n\n  .apiref-nav__scroll {\n    max-height: 60vh;\n  }\n\n  .apiref-nav.is-collapsed .apiref-nav__scroll {\n    display: none;\n  }\n\n  .apiref-nav__head {\n    position: relative;\n  }\n\n  .apiref-nav__head::after {\n    content: \"\u25be\";\n    position: absolute;\n    right: 0.8rem;\n    top: 0.75rem;\n    color: var(--ap-muted);\n    pointer-events: none;\n  }\n\n  .apiref-nav.is-collapsed .apiref-nav__head::after {\n    content: \"\u25b8\";\n  }\n}\n";
